using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Scenarios;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline runs the original per-call aggregate lookup in a loop; Optimized runs
// the agent-owned HotAggregateSolution.Summary in the same loop. Both aggregate
// the same orders server-side and return the same records, so only the per-call
// query-construction cost can differ. Do not edit this file — edit
// Scenarios/HotAggregate.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class HotAggregateBenchmark
{
    private SqliteConnection _connection = null!;
    private int[] _customerIds = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedCustomersWithOrders(db, customers: 300, ordersPerCustomer: 20);

        var rng = new Random(13);
        _customerIds = Enumerable.Range(0, 200).Select(_ => rng.Next(1, 301)).ToArray();

        EquivalenceGuard.SameResults(Baseline(), Optimized(), s => s.Name);
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<CustomerOrderSummary> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var results = new List<CustomerOrderSummary>(_customerIds.Length);
        foreach (var id in _customerIds)
        {
            results.Add(db.Customers
                .Where(c => c.Id == id)
                .Select(c => new CustomerOrderSummary(c.Name, c.Orders.Count, c.Orders.Sum(o => o.Total)))
                .First());
        }

        return results;
    }

    [Benchmark]
    public List<CustomerOrderSummary> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        var results = new List<CustomerOrderSummary>(_customerIds.Length);
        foreach (var id in _customerIds)
        {
            results.Add(HotAggregateSolution.Summary(db, id));
        }

        return results;
    }
}
